            if (thisY > 1.0f) {
              probeY = XYEncodingUtils.decode(XYEncodingUtils.encode(thisY));
            }
          } else if (thisY < 0.0f) {
            probeY = (float) thisMinY;
            if (thisY < -1.0f) {
              probeY = XYEncodingUtils.decode(XYEncodingUtils.encode(thisY));
            }
          }
        }
        boolean probeOk = thisShape.contains(probeX, probeY);
        return probeOk && point.x == x && point.y == y;
      }
      return false;
    }
